{"content":"import { createServerFn } from "@tanstack/react-start";
import { getRequestHeader } from "@tanstack/react-start/server";

export interface EffectivePrice {
  slug: string;
  price: number | null;
  uom: string | null;
  availability: string | null;
  mfrPartNumber: string | null;
  pickrelSku: string | null;
}

export interface EffectivePriceResult {
  customerId: string | null;
  prices: EffectivePrice[];
}

/**
 * Public price resolution.
 *
 * Guests get the default (list) pricing level. Signed-in users linked to a
 * customer account get that customer's negotiated / marked-up pricing.
 * Underlying product cost never leaves the server.
 */
export const getEffectivePrices = createServerFn({ method: "GET" }).handler(
  async (): Promise<EffectivePriceResult> => {
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");

    let customerId: string | null = null;
    const authHeader = getRequestHeader("authorization");
    const token = authHeader?.replace(/^Bearer\s+/i, "");
    if (token) {
      const { data } = await supabaseAdmin.auth.getUser(token);
      if (data.user) {
        const { data: profile } = await supabaseAdmin
          .from("profiles")
          .select("customer_id")
          .eq("id", data.user.id)
          .maybeSingle();
        customerId = profile?.customer_id ?? null;
      }
    }

    const { data, error } = await supabaseAdmin.rpc("price_list", {
      _customer_id: customerId as unknown as string,
    });
    if (error) {
      console.error("price_list failed", error.message);
      return { customerId, prices: [] };
    }

    const rows = (data ?? []) as Array<{
      slug: string;
      price: number | string | null;
      uom: string | null;
      availability: string | null;
      mfr_part_number: string | null;
      pickrel_sku: string | null;
    }>;

    return {
      customerId,
      prices: rows.map((r) => ({
        slug: r.slug,
        price: r.price === null ? null : Number(r.price),
        uom: r.uom,
        availability: r.availability,
        mfrPartNumber: r.mfr_part_number,
        pickrelSku: r.pickrel_sku,
      })),
    };
  },
);
